        vals = {(r, c): (5 if v == 5 else color) for r, c, v in cells}
        minr = min(r for r, c in vals)
        minc = min(c for r, c in vals)
        shape = {(r - minr, c - minc): v for (r, c), v in vals.items()}
        item = (color, shape)
        pieces.append(item)
