    full = (1 << area) - 1

    def rotate(shape):
        h = max(r for r, c in shape) + 1
        new = {(c, h - 1 - r): v for (r, c), v in shape.items()}
        mr = min(r for r, c in new)
        mc = min(c for r, c in new)
        return {(r - mr, c - mc): v for (r, c), v in new.items()}

    def orientations(shape):
        result = []
        cur = shape
        seen_shapes = set()
        for _ in range(4):
            key = tuple(sorted((r, c, v) for (r, c), v in cur.items()))
            if key not in seen_shapes:
                seen_shapes.add(key)
                result.append(cur)
            cur = rotate(cur)
        return result

    orients = [orientations(shape) for _, shape in pieces]
    placements = [[] for _ in pieces]
    bycell = [[[] for _ in range(area)] for _ in pieces]

