    def search(occ, used, chosen):
        if occ == full:
            return chosen if used == (1 << len(pieces)) - 1 else None

        empty = full ^ occ
        best = None
        best_options = None
        bits = empty
        while bits:
            bit = bits & -bits
            idx = bit.bit_length() - 1
            options = []
            for pi in range(len(pieces)):
                if used & (1 << pi):
